            self.log_dict[action] = []
        self.log_dict[action].append({
            'timestamp': timestamp,
            'action': action
        })
        self.write_log()

    def write_log(self):
        with open(self.log_file, 'w', encoding='utf-8') as file:
            json.dump(self.log_dict, file, ensure_ascii=False, indent=4)

# Example usage
